await tools.browser.wait({ tabID: t.id, condition: "load" });
const c = await tools.browser.console({ tabID: t.id, level: "error", limit: 50 });
const syntax = c.messages.filter(m => /SyntaxError|Unexpected token|Uncaught/.test(m.text));
const snap = await tools.browser.snapshot({ tabID: t.id });
return { syntaxErrors: syntax, errorCount: c.messages.length, firstErrors: c.messages.slice(0,5).map(m=>m.text.slice(0,200)), title: t.title };

const results = {};
for (const page of ["landing.html","legal.html","earn.html","auth.html"]) {
  const t = await tools.browser.tabs.open({ url: "http://127.0.0.1:8770/"+page });
  await tools.browser.wait({ tabID: t.id, condition: "load" });
  const r = await tools.browser.evaluate({ tabID: t.id, script: "(() => ({title:document.title, footer:[...document.querySelectorAll('footer, footer small, .fbottom')].map(e=>e.innerText.trim().slice(0,180)), imgs:[...document.images].filter(i=>i.src.includes('logo')).map(i=>({src:i.src.split('/').pop(),ok:i.naturalWidth>0}))}))()" });
  results[page] = r.value;
  await tools.browser.tabs.close({ tabID: t.id });
}
return results;

