```python
"""Phone access over the same Wi-Fi ..."""
from __future__ import annotations

import hashlib
import hmac
import ipaddress
import json
import secrets
import socket
import threading
import time
from pathlib import Path

from fastapi import Request
from fastapi.responses import HTMLResponse

from . import auth, config

FILE = config.DATA_DIR / "remote.json"
COOKIE = "ommydut_remote"
SESSION_DAYS = 30
_lock = threading.Lock()
_cache = {"m": 0, "d": {}}


def _read() -> dict:
    try:
        m = FILE.stat().st_mtime_ns
    except OSError:
        m = 0
    if _cache["m"] != m:
        try:
            d = json.loads(FILE.read_text(encoding="utf-8")) if m else {}
        except (OSError, ValueError):
            d = {}
        _cache.update(m=m, d=d if isinstance(d, dict) else {})
    return _cache["d"]


def _write(d: dict) -> None:
    with _lock:
        FILE.parent.mkdir(parents=True, exist_ok=True)
        tmp = FILE.with_suffix(".tmp")
        tmp.write_text(json.dumps(d, indent=1), encoding="utf-8")
        try:
            tmp.chmod(0o600)
        except OSError:
            pass
        tmp.replace(FILE)
        _cache["m"] = 0


def has_pin() -> bool:
    return bool(_read().get("pin"))

def enabled() -> bool:
    d = _read()
    return bool(d.get("enabled")) and bool(d.get("pin"))

def set_pin(pin: str) -> None:
    pin = str(pin or "").strip()
    if not pin.isdigit() or not 4 <= len(pin) <= 12:
        raise ValueError("Use 4 to 12 digits.")
    _write({"enabled": True, "pin": auth.hash_password(pin), "secret": secrets.token_hex(32)})

def disable() -> None:
    d = dict(_read())
    d["enabled"] = False
    d["secret"] = secrets.token_hex(32)
    _write(d)

def verify(pin: str) -> bool:
    d = _read()
    if not enabled():
        return False
    return auth.verify_password(str(pin or "").strip(), d["pin"])

def _signed() -> str:
    d = _read()
    secret = d.get("secret") or ""
    exp = int(time.time()) + SESSION_DAYS * 86400
    nonce = secrets.token_hex(12)
    body = f"{exp}.{nonce}"
    sig = hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()
    return body + "." + sig

def valid(req: Request) -> bool:
    if not enabled():
        return False
    raw = req.cookies.get(COOKIE, "")
    try:
        exp, nonce, sig = raw.split(".")
        if int(exp) < time.time():
            return False
        body = exp + "." + nonce
        secret = _read().get("secret") or ""
        want = hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()
        return hmac.compare_digest(sig, want)
    except Exception:
        return False

def grant(resp, req):
    resp.set_cookie(COOKIE, _signed(), max_age=SESSION_DAYS*86400, httponly=True, samesite="lax", secure=config.HTTPS, path="/")
    return resp

def clear(resp):
    resp.delete_cookie(COOKIE, path="/")
    return resp

def is_remote(req) -> bool:
    host = req.client.host if req.client else ""
    try:
        return not ipaddress.ip_address(host).is_loopback
    except ValueError:
        return False   # unknown client address: treat as local? safer to treat as remote...
