def local_ip() -> str:
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
    except OSError:
        ip = ""
    finally:
        s.close()
    if ip and not ip.startswith("127."):
        return ip
    try:
        for x in socket.gethostbyname_ex(socket.gethostname())[2]:
            if not x.startswith("127."):
                return x
    except OSError:
        pass
    return ""

def urls() -> list[str]:
    ip = local_ip()
    if not ip:
        return []
    return [f"http://{ip}:{config.PORT}/app"]

def url() -> str:
    u = urls()
    return u[0] if u else ""

