"""Remove paid-campaign/Earn UI and add Phone access, credit and mobile navigation."""
import re
import shutil
from pathlib import Path

ROOT = Path(r"C:\Users\soham\AppData\Local\Programs\ClipKontrast")
WORK = Path(r"C:\Users\soham\AppData\Local\Temp\ommydut-work")
P = ROOT / "app" / "web" / "index.html"
original = P.read_text(encoding="utf-8")
s = original
changes = []


def must(old, new, label, count=1):
    global s
    n = s.count(old)
    if n != count:
        raise RuntimeError(f"{label}: expected {count} match(es), found {n}")
