# ================================================================ phone access
@app.get("/phone-lock")
def phone_lock(next: str = "/app"):
    return HTMLResponse(remote.lock_html(next), headers={"Cache-Control": "private, no-store"})


@app.get("/api/remote/status")
def remote_status():
    return remote.status()


@app.post("/api/remote/setup")
def remote_setup(request: Request, body: dict = Body(...)):
    if not remote.local_request(request):
        raise HTTPException(403, "Phone access can only be changed on this computer.")
    try:
        remote.setup(str(body.get("pin", "")))
    except remote.AuthError as e:
        raise HTTPException(400, str(e))
    return {"ok": True, **remote.status()}


@app.post("/api/remote/disable")
def remote_disable(request: Request):
    if not remote.local_request(request):
        raise HTTPException(403, "Phone access can only be changed on this computer.")
    remote.disable()
    resp = JSONResponse({"ok": True, **remote.status()})
    resp.delete_cookie(remote.COOKIE, path="/")
    return resp


@app.post("/api/remote/unlock")
def remote_unlock(request: Request, body: dict = Body(...)):
    try:
        value = remote.unlock(str(body.get("pin", "")), _ip(request))
    except remote.AuthError as e:
        raise HTTPException(401, str(e))
    resp = JSONResponse({"ok": True})
    resp.set_cookie(remote.COOKIE, value, max_age=remote.MAX_AGE, httponly=True, samesite="lax",
                    secure=config.HTTPS, path="/")
    return resp


