"""Put the maker credit at the bottom of every public page, in both code copies."""
from pathlib import Path

ROOTS = [
    Path(r"C:\Users\soham\AppData\Local\Programs\ClipKontrast\app\web"),
    Path(r"C:\Users\soham\AppData\Local\Programs\ClipKontrast\app.old\web"),
]
FILES = ["landing.html", "auth.html", "download.html", "report.html", "legal.html", "admin.html", "reset.html"]
CREDIT = '<div class="maker-credit" style="text-align:center;padding:22px 16px 28px;color:#8b827b;font:12px system-ui,sans-serif">Built by Soham Chatterjee</div>\n'

for root in ROOTS:
    for name in FILES:
        p = root / name
        if not p.is_file():
            continue
        s = p.read_text(encoding="utf-8")
        if "Built by Soham Chatterjee" in s:
            continue
        if s.count("</body>") != 1:
            raise RuntimeError(f"{p}: expected one </body>, found {s.count('</body>')}")
        p.write_text(s.replace("</body>", CREDIT + "</body>"), encoding="utf-8")
print("Public credits restored")

