const tab = await tools.browser.tabs.open({ url: "http://127.0.0.1:8765/app", focus: true })
await tools.browser.wait({ tabID: tab.id, condition: "load", timeoutMs: 20000 })
const snap = await tools.browser.snapshot({ tabID: tab.id, depth: 8 })
const errors = await tools.browser.console({ tabID: tab.id, level: "error", limit: 30 })
const dom = await tools.browser.evaluate({ tabID: tab.id, script: `JSON.stringify({title:document.title, view:location.pathname+location.hash, ids:['o_wm','o_cam','o_tight','o_zoom','o_style','o_layout','addform','add','ov','remote'].map(id=>({id,exists:!!document.getElementById(id),visible:!!document.getElementById(id)&&!!document.getElementById(id).getClientRects().length})), text:document.querySelector('#view')?.innerText?.slice(0,1200)||''})` })
return { tab, snapshot: snap.content.slice(0, 6000), errors: errors.messages.map(m=>m.text), dom: JSON.parse(dom.value) }

const tabID = "tab_2211632d-f17b-4c48-82b0-17fdc6ac8d83"
await tools.browser.wait({ tabID, condition: "text", text: "Paste a link", timeoutMs: 20000 })
const dom = await tools.browser.evaluate({ tabID, script: `JSON.stringify({ready:document.readyState, view:location.pathname+location.hash, ids:['o_wm','o_cam','o_tight','o_zoom','o_style','o_layout','addform','add','ov','remote'].map(id=>({id,exists:!!document.getElementById(id),visible:!!document.getElementById(id)&&!!document.getElementById(id).getClientRects().length})), text:document.querySelector('#view')?.innerText?.slice(0,1600)||'', nav:document.querySelector('#nav')?.innerText?.slice(0,500)||''})` })
const snap = await tools.browser.snapshot({ tabID, depth: 10 })
const errors = await tools.browser.console({ tabID, level: "error", limit: 30 })
return { dom: JSON.parse(dom.value), snapshot: snap.content.slice(0, 9000), errors: errors.messages.map(m=>m.text) }

