/* ============================================================ phone access */
let R = {enabled:false, url:"", pin_set:false};
async function drawRemote() {
  const box = $("#remote"); if (!box) return;
  box.innerHTML = `<div class="card remote-card"><div class="rc-hero"><img src="/brand/logo-light.svg?v=ommycut2" alt="OmmyCut"><div><h2 style="margin:0">Phone access</h2><p class="help" style="margin:2px 0 0">Use this whole app from your phone while it is on the same Wi-Fi.</p></div></div>
    <div id="remoteBody"><p class="help">Checking status…</p></div></div>`;
  try {
    R = await api("/api/remote/status");
    const body = $("#remoteBody"); if (!body) return;
    body.innerHTML = `<p><span class="${R.enabled ? "rc-on" : "rc-off"}">${R.enabled ? "● Phone access is on" : "○ Phone access is off"}</span> · ${R.pin_set ? "A PIN is set." : "No PIN is set yet."}</p>
      ${R.enabled && R.url ? `<div class="remote-url"><code id="remoteUrl">${esc(R.url)}</code><button class="btn sm primary" data-act="remotecopy">Copy link</button></div>
        <ol class="remote-steps"><li>Connect your phone to the same Wi-Fi as this computer.</li><li>Open the link above in your phone's browser.</li><li>Enter the PIN you set below. Everything stays in sync live.</li></ol>`
        : `<p class="help">Set a 4–12 digit PIN to turn phone access on. Only your phone and this computer can use it.</p>`}
      <form class="remote-form" id="remoteForm" onsubmit="return false">
        <label>PIN<input id="remotePin" type="password" inputmode="numeric" pattern="[0-9]{4,12}" minlength="4" maxlength="12" placeholder="4–12 digits" autocomplete="new-password"></label>
        <label>Confirm PIN<input id="remotePin2" type="password" inputmode="numeric" pattern="[0-9]{4,12}" minlength="4" maxlength="12" placeholder="repeat it" autocomplete="new-password"></label>
        <button class="btn primary" data-act="remotesave">${R.pin_set ? "Change PIN" : "Set PIN & turn on"}</button>
      </form>
      ${R.pin_set ? `<p style="margin-top:14px"><button class="btn danger" data-act="remotedisable">Turn phone access off</button></p>` : ""}`;
  } catch (err) { const b = $("#remoteBody"); if (b) b.innerHTML = `<p class="help">${esc(err.message || "Could not load phone access.")}</p>`; }
}
async function remoteSave() {
  const pin = $("#remotePin")?.value.trim() || "", again = $("#remotePin2")?.value.trim() || "";
  if (!/^\d{4,12}$/.test(pin)) return toast("Use 4 to 12 digits.", "bad");
  if (pin !== again) return toast("The two PINs don't match.", "bad");
  try { await send("/api/remote/setup", {pin}); toast("Phone access is on.", "ok"); drawRemote(); }
  catch (err) { toast(err.message, "bad"); }
}
async function remoteDisable() {
  if (!await ask("Turn phone access off?", "Phones will no longer be able to connect, even with the PIN.", "Turn off", true)) return;
  try { await send("/api/remote/disable", {}); toast("Phone access is off.", "ok"); drawRemote(); }
  catch (err) { toast(err.message, "bad"); }
}
"""
