  /**
   * Exact tab ID returned by browser.tabs.open/list. Focus does not select a tool target.
   * @pattern ^tab_[a-f0-9-]{36}$
   */
  tabID: string,
}): Promise<{
  tab: {
    /** @pattern ^tab_[a-f0-9-]{36}$ */
    id: string,
    /** @maxLength 16384 */
    url: string,
    /** @maxLength 2048 */
    title: string,
    loading: boolean,
    /** @maxLength 2048 */
    loadError?: string,
    canGoBack: boolean,
    canGoForward: boolean,
    /** @integer @minimum 0 */
    generation: number,
  },
  files: Array<{
      /** @pattern ^file_[a-f0-9-]{36}$ */
      id: string,
      /** @maxLength 2048 */
      name: string,
      /** @maxLength 2048 */
      mime: string,
      /** @integer @minimum 0 */
      bytes: number,
      path: string,
    }>,
  scores: Array<{
      /** @maxLength 2048 */
      id: string,
      /** @maxLength 2048 */
      title: string,
      score: number | null,
    }>,
  failures: Array<{
      /** @maxLength 2048 */
      id: string,
      /** @maxLength 2048 */
      title: string,
      /** @maxLength 100000 */
      description: string,
    }>,
}>"}]

