param(
    [string]$RepoUrl = "https://github.com/cyzowebdev/ommycut.git",
    [string]$Branch = "main"
)

$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$InstallDir = Join-Path $env:LOCALAPPDATA "Programs\ClipKontrast"
$TempRoot = Join-Path $env:TEMP ("ommycut-install-" + [guid]::NewGuid().ToString("N"))
$Log = Join-Path $env:TEMP "ommycut-install.log"

function Log($msg) {
    $line = "[{0}] {1}" -f (Get-Date).ToString("s"), $msg
    Write-Host $line
    Add-Content -Path $Log -Value $line -ErrorAction SilentlyContinue
}

function Fail($msg) {
    Log "ERROR: $msg"
    Write-Host ""
    Write-Host "OmmyCut install failed. Details: $Log" -ForegroundColor Red
    Write-Host "Press Enter to close."
    Read-Host | Out-Null
    exit 1
}

function Get-WebFile($url, $path) {
    Log "Downloading $url"
    Invoke-WebRequest -Uri $url -OutFile $path -UseBasicParsing -TimeoutSec 900
}

function Get-ReleaseZip {
    $zip = Join-Path $TempRoot "ommycut-source.zip"
    $clean = $RepoUrl.TrimEnd('/', '.git')
    $urls = @(
        "https://github.com/cyzowebdev/ommycut/archive/refs/heads/$Branch.zip",
        "https://github.com/cyzowebdev/ommycut/archive/refs/heads/master.zip",
        "$clean/archive/refs/heads/$Branch.zip",
        "$clean/archive/refs/heads/master.zip"
    )
    foreach ($u in ($urls | Select-Object -Unique)) {
        try { Get-WebFile $u $zip; return $zip } catch { Log "Could not use $u" }
    }
    Fail "Could not download the OmmyCut source from GitHub. Check the repo URL and your internet connection."
}

function Expand-Source($zip) {
    $out = Join-Path $TempRoot "source"
    Expand-Archive -Path $zip -DestinationPath $out -Force
    $root = Get-ChildItem $out -Directory | Where-Object { $_.Name -like 'ommycut-*' } | Select-Object -First 1
    if (-not $root) { $root = Get-Item $out }
    return $root.FullName
}

function Install-Source($src) {
    Log "Installing OmmyCut files to $InstallDir"
    New-Item -ItemType Directory -Path $InstallDir -Force | Out-Null
    # Keep the user's data folder, settings, clips and local overrides.
    $copy = @("app", "web", "python", "ffmpeg", "update")
    foreach ($name in $copy) {
        $from = Join-Path $src $name
        if (Test-Path $from) {
            Copy-Item -Path $from -Destination (Join-Path $InstallDir $name) -Recurse -Force
        }
    }
    foreach ($file in (Get-ChildItem $src -File)) {
        if ($file.Name -eq ".env") { continue }
        Copy-Item -Path $file.FullName -Destination (Join-Path $InstallDir $file.Name) -Force
    }
    $example = Join-Path $InstallDir ".env.example"
    $envFile = Join-Path $InstallDir ".env"
    if ((Test-Path $example) -and -not (Test-Path $envFile)) { Copy-Item $example $envFile -Force }
    New-Item -ItemType Directory -Path (Join-Path $InstallDir "data\logs") -Force | Out-Null
}

function Install-Python {
    $py = Join-Path $InstallDir "python\python.exe"
    if (Test-Path $py) { Log "Python runtime already present."; return }
    Log "Downloading Python 3.12.10 (embedded runtime)."
    $pydir = Join-Path $InstallDir "python"
    New-Item -ItemType Directory -Path $pydir -Force | Out-Null
    $pyzip = Join-Path $TempRoot "python.zip"
    Get-WebFile "https://www.python.org/ftp/python/3.12.10/python-3.12.10-embed-amd64.zip" $pyzip
    Expand-Archive -Path $pyzip -DestinationPath $pydir -Force
    $pth = Join-Path $pydir "python312._pth"
    @("python312.zip", ".", "Lib\site-packages", "..\app", "import site") | Set-Content -Path $pth -Encoding ASCII
    Copy-Item (Join-Path $pydir "pythonw.exe") (Join-Path $pydir "OmmyCut.exe") -Force
    $getpip = Join-Path $TempRoot "get-pip.py"
    Get-WebFile "https://bootstrap.pypa.io/get-pip.py" $getpip
    Log "Installing pip."
    & $py $getpip --disable-pip-version-check --no-warn-script-location | ForEach-Object { Log $_ }
    if ($LASTEXITCODE -ne 0) { Fail "pip installation failed." }
}

function Install-Requirements {
    $py = Join-Path $InstallDir "python\python.exe"
    $req = Join-Path $InstallDir "app\requirements.txt"
    if (-not (Test-Path $req)) { Fail "requirements.txt is missing from the downloaded source." }
    Log " Installing Python packages (this can take several minutes)."
    & $py -m pip install --disable-pip-version-check --no-warn-script-location -r $req | ForEach-Object { Log $_ }
    if ($LASTEXITCODE -ne 0) { Fail "Installing Python packages failed." }
}

function Install-Ffmpeg {
    $ff = Join-Path $InstallDir "ffmpeg\bin\ffmpeg.exe"
    if (Test-Path $ff) { Log "ffmpeg already present."; return }
    Log "Installing ffmpeg."
    try {
        winget install --id Gyan.FFmpeg -e --accept-source-agreements --accept-package-agreements --silent | Out-Null
        $cmd = Get-Command ffmpeg -ErrorAction SilentlyContinue
        if ($cmd) {
            $ffdir = Join-Path $InstallDir "ffmpeg\bin"
            New-Item -ItemType Directory -Path $ffdir -Force | Out-Null
            Copy-Item $cmd.Source (Join-Path $ffdir "ffmpeg.exe") -Force
            return
        }
    } catch { Log "winget was not available; downloading a portable ffmpeg." }
    $zip = Join-Path $TempRoot "ffmpeg.zip"
    Get-WebFile "https://www.gyan.dev/ffmpeg/builds/ffmpeg-release-essentials.zip" $zip
    $out = Join-Path $TempRoot "ffmpeg"
    Expand-Archive -Path $zip -DestinationPath $out -Force
    $exe = Get-ChildItem $out -Recurse -Filter ffmpeg.exe | Select-Object -First 1
    if (-not $exe) { Fail "The ffmpeg download did not contain ffmpeg.exe." }
    $ffdir = Join-Path $InstallDir "ffmpeg\bin"
    New-Item -ItemType Directory -Path $ffdir -Force | Out-Null
    Copy-Item $exe.FullName (Join-Path $ffdir "ffmpeg.exe") -Force
    $ffprobe = Get-ChildItem $out -Recurse -Filter ffprobe.exe | Select-Object -First 1
    if ($ffprobe) { Copy-Item $ffprobe.FullName (Join-Path $ffdir "ffprobe.exe") -Force }
}

function Make-Shortcuts {
    Log "Creating OmmyCut shortcuts."
    $exe = Join-Path $InstallDir "python\OmmyCut.exe"
    if (-not (Test-Path $exe)) { Copy-Item (Join-Path $InstallDir "python\pythonw.exe") $exe -Force }
    $icon = Join-Path $InstallDir "ommycut.ico"
    $start = Join-Path $env:APPDATA "Microsoft\Windows\Start Menu\Programs\OmmyCut"
    New-Item -ItemType Directory -Path $start -Force | Out-Null
    $wsh = New-Object -ComObject WScript.Shell
    $targets = @(
        (Join-Path $env:USERPROFILE "Desktop\OmmyCut.lnk"),
        (Join-Path $start "OmmyCut.lnk"),
        (Join-Path $env:APPDATA "Microsoft\Windows\Start Menu\Programs\OmmyCut.lnk")
    )
    foreach ($lnk in $targets) {
        $s = $wsh.CreateShortcut($lnk)
        $s.TargetPath = $exe
        $s.Arguments = "-m studio.desktop"
        $s.WorkingDirectory = $InstallDir
        $s.IconLocation = "$icon,0"
        $s.Description = "OmmyCut"
        $s.Save()
    }
    New-Item -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\OmmyCut" -Force | Out-Null
    Set-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\OmmyCut" -Name DisplayName -Value "OmmyCut"
    Set-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\OmmyCut" -Name DisplayIcon -Value $icon
    Set-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\OmmyCut" -Name InstallLocation -Value $InstallDir
    Set-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\OmmyCut" -Name Publisher -Value "Soham Chatterjee"
    Set-ItemProperty "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\OmmyCut" -Name DisplayVersion -Value "1.0.0"
}

try {
    New-Item -ItemType Directory -Path $TempRoot -Force | Out-Null
    Log "OmmyCut installer started. Repo: $RepoUrl"
    $zip = Get-ReleaseZip
    $src = Expand-Source $zip
    Install-Source $src
    Install-Python
    Install-Requirements
    Install-Ffmpeg
    Make-Shortcuts
    Log "Starting OmmyCut."
    Start-Process -FilePath (Join-Path $InstallDir "python\OmmyCut.exe") -ArgumentList "-m studio.desktop" -WorkingDirectory $InstallDir
    Log "Done. OmmyCut was installed to $InstallDir"
    Write-Host ""
    Write-Host "OmmyCut installed successfully." -ForegroundColor Green
    Write-Host "It is on your Desktop and in the Start menu." -ForegroundColor Green
} catch {
    Fail $_.Exception.Message
}

