const tab = await tools.browser.tabs.open({url:"http://127.0.0.1:8765/app", focus:false});
await tools.browser.wait({tabID:tab.id, condition:"load"});
const errors = await tools.browser.console({tabID:tab.id, level:"error"});
const info = await tools.browser.evaluate({tabID:tab.id, expression:`(() => {
  const txt = document.body.innerText;
  const mnav = document.querySelector('.mnav');
  const topLogo = document.querySelector('.top-logo');
  return {
    title: document.title,
    hasReport: /Report a problem|Report this/.test(txt),
    hasUpdate: /Check for updates|Check now/.test(txt),
    hasCampaign: /Paid campaigns|Earn campaigns|Send to a campaign/.test(txt),
    topLogoSrc: topLogo?.getAttribute('src'),
    topLogoVisible: topLogo ? getComputedStyle(topLogo).display : null,
    mnavDisplay: mnav ? getComputedStyle(mnav).display : null,
    mnavBg: mnav ? getComputedStyle(mnav).backgroundColor : null,
    mnavBtnColor: mnav?.querySelector('button') ? getComputedStyle(mnav.querySelector('button')).color : null,
    navText: [...document.querySelectorAll('#nav .nav-item')].map(b=>b.innerText.trim()),
    newsText: txt.slice(0,400)
  };
})()`});
return {tab:tab.id, errors:errors.messages, info:info.value ?? info};

