def _state_file() -> Path:
    """There is exactly one live PIN file: <install>/data/remote.json.

    Older builds also left copies in app/data or in a custom data folder. Any launcher that misses the install
    environment variables would read one of those stale copies and reject the current PIN after a restart. Bring a
    valid copy forward, then rename every other copy so no launch path can ever disagree about the PIN or secret.
    """
    install_data = Path(config.INSTALL_DIR) / "data" if getattr(config, "INSTALL_DIR", None) else None
    if install_data:
        try:
            install_data.mkdir(parents=True, exist_ok=True)
        except OSError:
            install_data = None
    target = (install_data / "remote.json") if install_data else config.DATA_DIR / "remote.json"
    try:
        target.parent.mkdir(parents=True, exist_ok=True)
    except OSError:
        pass

    def valid(path: Path) -> bool:
        try:
            state = json.loads(path.read_text(encoding="utf-8"))
            return isinstance(state, dict) and bool(state.get("pin_hash")) and bool(state.get("secret"))
        except Exception:
            return False

    candidates = []
    for base in (config.DATA_DIR, Path(config.ROOT) / "data"):
        if not base:
            continue
        base = Path(base)
        candidates.extend((base / "remote.json", base / "remote.json.legacy"))
    seen = set()
    if not valid(target):
        for src in candidates:
            try:
                key = str(src.resolve())
            except OSError:
                key = str(src)
            if key in seen or key == str(target.resolve()) or not valid(src):
                continue
            seen.add(key)
            try:
                shutil.copy2(src, target)
                break
            except OSError:
                try:
                    os.replace(src, target)
                    break
                except OSError:
                    pass

    # Retire stale copies even when the canonical file is good: a different launcher must not read another PIN.
    for src in candidates:
        try:
            if src.exists() and src.resolve() != target.resolve():
                retired = Path(str(src) + ".legacy")
                if retired.exists():
                    retired.unlink()
                os.replace(src, retired)
        except OSError:
            pass
    return target

