            if (failed)
            {
                using (SolidBrush alert = new SolidBrush(Color.FromArgb(220, 255, 92, 92)))
                    g.FillRectangle(alert, 0, 0, Width, 4);
            }
        }

        private void DrawLogo(Graphics g, Rectangle rect, float alpha)
        {
            if (logo == null || alpha <= 0f) return;
            using (ImageAttributes ia = new ImageAttributes())
            {
                ColorMatrix matrix = new ColorMatrix();
                matrix.Matrix33 = Math.Max(0f, Math.Min(1f, alpha));
                ia.SetColorMatrix(matrix, ColorMatrixFlag.Default, ColorAdjustType.Bitmap);
                g.DrawImage(logo, rect, 0, 0, logo.Width, logo.Height, GraphicsUnit.Pixel, ia);
            }
        }

        private static void DrawCentered(Graphics g, string text, Rectangle rect, Font font, Brush brush)
        {
            if (String.IsNullOrEmpty(text)) return;
            StringFormat format = new StringFormat();
            format.Alignment = StringAlignment.Center;
            format.LineAlignment = StringAlignment.Center;
            g.DrawString(text, font, brush, rect, format);
            format.Dispose();
        }

        private static GraphicsPath RoundRect(Rectangle r, int radius)
        {
            GraphicsPath path = new GraphicsPath();
            int d = Math.Min(radius * 2, Math.Min(r.Width, r.Height));
            path.AddArc(r.X, r.Y, d, d, 180, 90);
            path.AddArc(r.Right - d, r.Y, d, d, 270, 90);
            path.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
            path.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
            path.CloseFigure();
            return path;
        }

        protected override void OnClick(EventArgs e)
        {
            if (failed || done) Close();
            base.OnClick(e);
        }

        protected override void OnKeyDown(KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Escape) Close();
            base.OnKeyDown(e);
        }

        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            if (child != null && !child.HasExited)
            {
                try { child.Kill(); } catch { }
            }
            if (!String.IsNullOrEmpty(tempDir))
            {
                try { Directory.Delete(tempDir, true); } catch { }
            }
            base.OnFormClosing(e);
        }
    }

    internal static class Program
    {
        [STAThread]
        private static void Main(string[] args)
        {
            try { SetProcessDPIAware(); } catch { }
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            bool preview = args.Length > 0 && String.Equals(args[0], "--preview", StringComparison.OrdinalIgnoreCase);
            Application.Run(new Splash(preview));
        }

        [DllImport("user32.dll")]
        private static extern bool SetProcessDPIAware();
    }
}

