@app.post("/api/ommy-update/check")
def ommy_update_check(request: Request):
    """The Settings > Check for update tab: look in the owner's GitHub repo for a newer numbered zip."""
    u = getattr(request.state, "user", None)
    if not u or not u.is_admin:
        raise HTTPException(404, "Not found.")
    from . import ommy_update
    return ommy_update.check_now()


@app.post("/api/ommy-update/apply")
def ommy_update_apply(request: Request):
    u = getattr(request.state, "user", None)
    if not u or not u.is_admin:
        raise HTTPException(404, "Not found.")
    from . import ommy_update
    try:
        return ommy_update.apply()
    except RuntimeError as e:
        raise HTTPException(400, str(e))


