/* On-demand GitHub update: the Settings tab and the full-screen branded progress animation. */
.upd-hero{display:flex;align-items:center;gap:16px;flex-wrap:wrap;background:linear-gradient(135deg,#1E1612,#2E211A);border:1px solid #C6F43255;border-radius:18px;padding:18px 20px;color:#fff;margin:4px 0 18px;box-shadow:0 12px 34px rgba(30,22,18,.18)}
