.upd-stage .u-orbit::before{left:14px;top:44px}
.upd-stage .u-orbit::after{right:14px;bottom:44px;opacity:.6}
.upd-logo{position:relative;height:88px;width:auto;max-width:88%;display:block;margin:0 auto 14px;filter:drop-shadow(0 10px 26px rgba(198,244,50,.22));animation:updFloat 3s ease-in-out infinite}
