/* Settings > Check for update: looks in the owner's GitHub repo and, when a higher numbered zip is there, updates
   straight away with a smooth branded animation. No background checking, no second button to hunt for. */
function ommyShell() {
  let el = $("#ommyOverlay");
  if (!el) {
    el = document.createElement("div");
    el.id = "ommyOverlay"; el.className = "upd-overlay"; el.setAttribute("aria-live", "polite");
    el.innerHTML = `<div class="upd-stage"><div class="u-glow"></div><div class="u-orbit"></div>
      <img class="upd-logo" src="/brand/logo-light.svg?v=ommycut2" alt="OmmyCut">
      <div class="upd-ring"><span>0%</span></div>
      <h2>Checking GitHub…</h2><p>Looking for a newer numbered OmmyCut zip.</p>
      <div class="upd-steps"><i>Check</i><i>Download</i><i>Install</i><i>Restart</i></div>
      <div class="upd-bar"><b></b></div><div class="upd-credit">Built by Soham Chatterjee</div></div>`;
    document.body.append(el);
  }
  return el;
}
function ommyPaint(phase, pct, title, msg) {
  const el = ommyShell(), n = Math.max(0, Math.min(100, Math.round(pct || 0)));
  el.classList.add("on");
  el.querySelector(".upd-ring").style.setProperty("--p", n);
  el.querySelector(".upd-ring span").textContent = n + "%";
  el.querySelector("h2").textContent = title;
  el.querySelector("p").textContent = msg;
  el.querySelector(".upd-bar b").style.width = n + "%";
  const at = {checking:0, downloading:1, installing:2, restarting:3, error:-1}[phase] ?? 0;
  [...el.querySelectorAll(".upd-steps i")].forEach((s, i) => s.classList.toggle("on", i <= at));
}
function ommyClose() { $("#ommyOverlay")?.classList.remove("on"); }
async function ommyCheck(btn) {
  const label = btn ? btn.innerHTML : "";
  if (btn) { btn.disabled = true; btn.innerHTML = `${ic("up")}<span class="label">Checking…</span>`; }
  ommyPaint("checking", 8, "Checking GitHub…", "Looking for a newer numbered OmmyCut zip.");
  try {
    const r = await api("/api/ommy-update/check", {method: "POST"});
    S.ommyUpdate = r.update;
    if (r.update) {
      ommyPaint("checking", 14, "New version found", `${r.current} → ${r.latest}. Starting the update…`);
      await new Promise(ok => setTimeout(ok, 750));
      return ommyInstall();
    }
    ommyClose();
    toast(r.reached ? `You have the newest version (${r.current}). 🎉`
                    : (r.error || "Could not reach GitHub. Check your internet and try again."), r.reached ? "ok" : "bad");
  } catch (e) { ommyClose(); toast(e.message || "Could not check right now.", "bad"); }
  finally { if (btn && btn.isConnected) { btn.disabled = false; btn.innerHTML = label; } }
}
async function ommyInstall() {
  if (!S.ommyUpdate) {
    const r = await api("/api/ommy-update/check", {method: "POST"});
    S.ommyUpdate = r.update;
    if (!r.update) { toast(r.error || `You have the newest version (${r.current}).`, r.reached ? "ok" : "bad"); return; }
  }
  const before = S.ommyUpdate.latest || "", started = Date.now();
  try {
    ommyPaint("downloading", 18, "Updating OmmyCut…", `Getting ${S.ommyUpdate.zip || "the newest version"}.`);
    await api("/api/ommy-update/apply", {method: "POST"});
    for (;;) {
      await new Promise(ok => setTimeout(ok, 450));
      let p;
      try { p = await api("/api/ommy-update/progress", {cache: "no-store"}); }
      catch (e) { if (Date.now() - started > 9000) { location.reload(); return; } continue; }
      if (p.phase === "error") { ommyClose(); toast(p.error || "The update didn't work. Nothing was changed.", "bad"); return; }
      const titles = {downloading:"Downloading the new version", installing:"Installing the new version",
                      restarting:"Restarting OmmyCut"};
      ommyPaint(p.phase, Math.round((p.progress || 0) * 100), titles[p.phase] || "Updating OmmyCut…",
                p.message || "Your clips, settings and PIN stay exactly as they are.");
      if (p.phase === "restarting") { await new Promise(ok => setTimeout(ok, 1900)); location.reload(); return; }
      if (p.version && p.version !== before && p.phase === "idle") { location.reload(); return; }
    }
  } catch (e) { ommyClose(); toast(e.message || "Could not start the update.", "bad"); }
}
function greeting() { const h = new Date().getHours(); return h < 12 ? "Good morning" : h < 18 ? "Good afternoon" : "Good evening"; }

