from pathlib import Path
import hashlib

LIVE = Path(r"C:\Users\soham\AppData\Local\Programs\ClipKontrast\app")
OLD = Path(r"C:\Users\soham\AppData\Local\Programs\ClipKontrast\app.old")
REPO = Path(r"C:\Users\soham\release\ommycut-repo\app")
SKIP_DIRS = {"__pycache__", "data", "models", "tmp", "logs", "users", ".git"}
SKIP_NAMES = {".DS_Store", "Thumbs.db"}


def files(root):
    out = {}
    if not root.exists():
        return out
    for p in root.rglob("*"):
        if not p.is_file():
            continue
        rel = p.relative_to(root)
        if any(part in SKIP_DIRS for part in rel.parts) or p.name in SKIP_NAMES or p.suffix == ".pyc":
            continue
        out[rel.as_posix()] = hashlib.sha256(p.read_bytes()).hexdigest()
    return out


live, old, repo = files(LIVE), files(OLD), files(REPO)
print("counts", len(live), len(old), len(repo))
for label, other in (("OLD", old), ("REPO", repo)):
    missing = sorted(set(live) - set(other))
    extra = sorted(set(other) - set(live))
    diff = sorted(k for k in set(live) & set(other) if live[k] != other[k])
    print(f"\n{label}: missing_from_other={len(missing)} extra_in_other={len(extra)} different={len(diff)}")
    for k in missing[:40]:
        print("  LIVE-ONLY", k)
    for k in extra[:40]:
        print("  OTHER-ONLY", k)
    for k in diff[:80]:
        print("  DIFF", k)

from pathlib import Path
import shutil

LIVE = Path(r"C:\Users\soham\AppData\Local\Programs\ClipKontrast\app")
TARGETS = [
    Path(r"C:\Users\soham\AppData\Local\Programs\ClipKontrast\app.old"),
    Path(r"C:\Users\soham\release\ommycut-repo\app"),
]
SKIP_DIRS = {"__pycache__", "data", "models", "tmp", "logs", "users", ".git"}
SKIP_NAMES = {".DS_Store", "Thumbs.db"}

for target in TARGETS:
    count = 0
    for src in LIVE.rglob("*"):
        if not src.is_file():
            continue
        rel = src.relative_to(LIVE)
        if any(part in SKIP_DIRS for part in rel.parts) or src.name in SKIP_NAMES or src.suffix == ".pyc":
            continue
        dst = target / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        if not dst.exists() or src.read_bytes() != dst.read_bytes():
            shutil.copy2(src, dst)
            count += 1
    print("synced", target, count)

