function Test-ZipFile($path) {
    if (-not (Test-Path -LiteralPath $path)) { return $false }
    if ((Get-Item -LiteralPath $path).Length -lt 100) { return $false }
    $fs = [IO.File]::OpenRead($path)
    try {
        $head = New-Object byte[] 4
        $read = $fs.Read($head, 0, 4)
        return ($read -eq 4 -and $head[0] -eq 0x50 -and $head[1] -eq 0x4B)
    } catch { return $false } finally { $fs.Dispose() }
}

function Get-ReleaseZip {
    $zip = Join-Path $TempRoot "ommycut-source.zip"
    $clean = $RepoUrl -replace '/$', '' -replace '\.git$', ''
    $urls = @(
        "https://github.com/cyzowebdev/ommycut/archive/refs/heads/$Branch.zip",
        "https://github.com/cyzowebdev/ommycut/archive/refs/heads/master.zip",
        "$clean/archive/refs/heads/$Branch.zip",
        "$clean/archive/refs/heads/master.zip"
    )
    foreach ($u in ($urls | Select-Object -Unique)) {
        try {
            Get-WebFile $u $zip
            if (Test-ZipFile $zip) { return $zip }
            Log "GitHub returned a page instead of a zip file for $u"
        } catch { Log "Could not use $u" }
    }
    Fail "OmmyCut is not published on GitHub yet. Upload the repo to https://github.com/cyzowebdev/ommycut, then run this installer again."
}

function Expand-Source($zip) {
    $out = Join-Path $TempRoot "source"
    if (-not (Test-ZipFile $zip)) {
        Fail "The download was not a valid OmmyCut zip. If the repo has not been uploaded yet, publish it first and run the installer again."
    }
    try { Expand-Archive -Path $zip -DestinationPath $out -Force }
    catch { Fail "The download was not a valid OmmyCut zip. If the repo has not been uploaded yet, publish it first and run the installer again." }

