input.newString:
function Expand-Source($zip) {
    $out = Join-Path $TempRoot "source"
    if (-not (Test-ZipFile $zip)) {
        Fail "The download was not a valid OmmyCut zip. If the repo has not been uploaded yet, publish it first and run the installer again."
    }
    try { Expand-Archive -Path $zip -DestinationPath $out -Force }
    catch { Fail "The download was not a valid OmmyCut zip. If the repo has not been uploaded yet, publish it first and run the installer again." }
    $root = Get-ChildItem $out -Directory | Where-Object { $_.Name -like 'ommycut-*' } | Select-Object -First 1
    if (-not $root) { $root = Get-Item $out }

    # The repo may have been uploaded as the source ZIP itself instead of its extracted
    # contents. Detect that and unpack it so installation still works.
    $inner = Get-ChildItem -LiteralPath $root.FullName -File -Filter 'OmmyCut-GitHub*.zip' -ErrorAction SilentlyContinue |
             Select-Object -First 1
    if ($inner) {
        Log "Found $($inner.Name) in the repo; unpacking it automatically."
        $innerOut = Join-Path $TempRoot "source-inner"
        try { Expand-Archive -Path $inner.FullName -DestinationPath $innerOut -Force }
        catch { Fail "The OmmyCut source zip in the repo could not be opened." }
        $innerRoot = Get-ChildItem $innerOut -Directory | Select-Object -First 1
        if ($innerRoot) { return $innerRoot.FullName }
        return $innerOut
    }
    return $root.FullName
}

