content.text:
+/* ---------- OmmyCut: phone access, mobile navigation and credit */
+.top-logo{display:none;height:26px;width:auto;align-self:center;margin-left:2px}
+.side-credit{font-size:11.5px;color:var(--faint);padding:10px 14px 4px;text-align:center}
+.app-credit{text-align:center;font-size:12px;color:var(--faint);padding:14px 16px 26px;border-top:1px solid var(--line)}
+.mnav{display:none}
+.mnav svg{width:21px;height:21px;fill:currentColor;stroke:none}
+.mnav button{color:inherit}
+.remote-card{max-width:780px;margin:0 auto}
+.remote-card .rc-hero{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:6px}
+.remote-card .rc-hero img{height:40px;width:auto}
+.remote-card .rc-on{color:#1B7A32;font-weight:700}
+.remote-card .rc-off{color:var(--dim);font-weight:700}
+.remote-url{display:flex;gap:8px;align-items:center;flex-wrap:wrap;background:var(--brand-soft);border:1px solid var(--brand);border-radius:12px;padding:12px 14px;margin:10px 0}
+.remote-url code{flex:1;min-width:180px;font-size:14px;overflow-wrap:anywhere;user-select:all}
+.remote-steps{margin:12px 0 0;padding-left:20px;line-height:1.8;font-size:13.5px;color:var(--dim)}
+.remote-form{display:flex;gap:10px;flex-wrap:wrap;align-items:end;margin-top:12px}
+.remote-form label{display:flex;flex-direction:column;gap:5px;font-size:12.5px;color:var(--dim)}
+.remote-form input{font-size:16px;padding:10px 12px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:inherit;width:170px;letter-spacing:2px}
+/* On-demand GitHub update: the Settings tab and the full-screen branded progress animation. */
+.upd-hero{display:flex;align-items:center;gap:16px;flex-wrap:wrap;background:linear-gradient(135deg,#1E1612,#2E211A);border:1px solid #C6F43255;border-radius:18px;padding:18px 20px;color:#fff;margin:4px 0 18px;box-shadow:0 12px 34px rgba(30,22,18,.18)}
+.upd-hero img{height:40px;width:auto;object-fit:contain;max-width:160px;background:#FFFFFF;padding:7px 11px;border-radius:12px;border:1px solid rgba(255,255,255,.9);box-shadow:0 5px 18px rgba(0,0,0,.28);filter:none;image-rendering:auto}
+.upd-hero .u-txt{flex:1;min-width:180px}
+.upd-hero .u-txt b{display:block;font-size:19px;letter-spacing:-.02em}
+.upd-hero .u-txt span{display:block;color:#C9BCB2;font-size:12.5px;margin-top:3px}
+.upd-hero .pill{border-color:#C6F43266;color:#C6F432;background:#C6F43214}
+.upd-card{border:1px solid var(--line);border-radius:16px;padding:18px;background:var(--card);box-shadow:0 8px 22px rgba(42,26,18,.06)}
+.upd-card h3{margin:0 0 8px;font-size:16px}
+.upd-card .u-ver{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:10px 0 14px}
+.upd-card code{font-size:12.5px;background:var(--muted);padding:4px 9px;border-radius:8px}
+.upd-card .u-arrow{color:var(--brand-ink);font-weight:800}
+.upd-card .u-notes{margin:10px 0 0;padding-left:18px;color:var(--dim);font-size:13px;line-height:1.7}
+.upd-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}
+.upd-msg{font-size:12.5px;color:var(--dim);margin-top:10px;min-height:18px}
+.upd-overlay{position:fixed;inset:0;z-index:2000;display:grid;place-items:center;padding:20px;background:radial-gradient(circle at 50% 38%,rgba(198,244,50,.13),transparent 42%),linear-gradient(160deg,#100C0A,#241A15 55%,#100C0A);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);opacity:0;pointer-events:none;transition:opacity .35s ease}
+.upd-overlay.on{opacity:1;pointer-events:auto}
+.upd-stage{width:min(560px,94vw);text-align:center;color:#F4EEEA;position:relative;padding:34px 26px 28px;border-radius:26px;border:1px solid rgba(198,244,50,.22);background:linear-gradient(180deg,rgba(255,255,255,.055),rgba(255,255,255,.015));box-shadow:0 30px 90px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.08);transform:translateY(18px) scale(.97);transition:transform .45s cubic-bezier(.2,.8,.2,1)}
+.upd-overlay.on .upd-stage{transform:none}
+.upd-stage .u-glow{position:absolute;left:50%;top:196px;width:360px;height:220px;transform:translate(-50%,-50%);background:radial-gradient(ellipse,rgba(198,244,50,.20),transparent 68%);filter:blur(6px);animation:updGlow 3.4s ease-in-out infinite;pointer-events:none}
+.upd-stage .u-orbit{position:absolute;left:50%;top:196px;width:400px;height:170px;margin-left:-200px;border:1px solid rgba(198,244,50,.13);border-radius:50%;pointer-events:none;animation:updOrbit 12s linear infinite}
+.upd-stage .u-orbit::before,.upd-stage .u-orbit::after{content:"";position:absolute;width:7px;height:7px;border-radius:50%;background:#C6F432;box-shadow:0 0 18px 5px rgba(198,244,50,.35)}
+.upd-stage .u-orbit::before{left:14px;top:44px}
+.upd-stage .u-orbit::after{right:14px;bottom:44px;opacity:.6}
+.upd-logo-plate{position:relative;display:inline-flex;align-items:center;justify-content:center;margin:0 auto 14px;padding:12px 18px;border-radius:18px;background:#FFFFFF;border:1px solid rgba(255,255,255,.92);box-shadow:0 12px 34px rgba(0,0,0,.32),0 0 0 4px rgba(198,244,50,.10);animation:updLogoPulse 3.2s ease-in-out infinite}
+.upd-logo{position:relative;height:76px;width:auto;max-width:100%;display:block;filter:none;image-rendering:auto}
+.upd-ring{--p:0;position:relative;width:92px;height:92px;margin:0 auto 18px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(#C6F432 calc(var(--p) * 1%),rgba(255,255,255,.10) 0);box-shadow:0 0 30px rgba(198,244,50,.12);transition:background .4s ease}
+.upd-ring::before{content:"";position:absolute;inset:8px;border-radius:50%;background:#1E1612}
+.upd-ring span{position:relative;font-size:15px;font-weight:800;color:#C6F432;font-variant-numeric:tabular-nums}
+.upd-stage h2{margin:0 0 7px;font-size:21px;letter-spacing:-.02em}
+.upd-stage p{margin:0 auto;max-width:440px;color:#C9BCB2;font-size:13px;line-height:1.6;min-height:21px}
+.upd-steps{display:flex;justify-content:center;gap:7px;flex-wrap:wrap;margin-top:22px}
+.upd-steps i{font-style:normal;font-size:11px;color:#8F8177;border:1px solid rgba(255,255,255,.09);border-radius:999px;padding:5px 10px;transition:all .3s ease}
+.upd-steps i.on{color:#1E1612;background:#C6F432;border-color:#C6F432;font-weight:700;box-shadow:0 0 18px rgba(198,244,50,.25)}
+.upd-bar{height:5px;border-radius:99px;background:rgba(255,255,255,.09);overflow:hidden;margin:18px auto 0;max-width:380px}
+.upd-bar b{display:block;height:100%;width:0;border-radius:99px;background:linear-gradient(90deg,#8FCB22,#C6F432,#E8FFB0);transition:width .35s ease;box-shadow:0 0 16px rgba(198,244,50,.45)}
+.upd-credit{margin-top:16px;color:#8F8177;font-size:11px}
+@keyframes updLogoPulse{0%,100%{box-shadow:0 12px 34px rgba(0,0,0,.32),0 0 0 4px rgba(198,244,50,.10)}50%{box-shadow:0 12px 34px rgba(0,0,0,.32),0 0 0 8px rgba(198,244,50,.20)}}
+@keyframes updGlow{0%,100%{opacity:.65;transform:translate(-50%,-50%) scale(1)}50%{opacity:1;transform:translate(-50%,-50%) scale(1.12)}}
+@keyframes updOrbit{to{transform:rotate(360deg)}}
+@media (max-width:900px){
+  .top-logo{display:block;height:22px}
+  .mnav{display:grid;position:fixed;left:10px;right:10px;bottom:10px;z-index:60;grid-template-columns:repeat(4,1fr);background:#1E1612;border:2px solid #C6F432;border-radius:18px;padding:5px;box-shadow:0 10px 32px rgba(0,0,0,.35)}
+  .mnav button{border:0;background:none;color:#FFFFFF;font:inherit;font-size:11px;font-weight:700;display:flex;flex-direction:column;align-items:center;gap:2px;padding:6px 2px;border-radius:12px;cursor:pointer}
+  .mnav button svg{color:#FFFFFF;fill:#FFFFFF}
+  .mnav button.on{background:#C6F432;color:#1E1612}
+  .mnav button.on svg{color:#1E1612;fill:#1E1612}
+  .content{padding-bottom:96px!important}
+  .app-credit{padding-bottom:86px}
+}
 </style>
