using System;
using System.Text;
using System.Runtime.InteropServices;
public class WinEnum {
  public delegate bool EnumProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc proc, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder text, int max);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint pid);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int cmd);
}
"@

$exe = "C:\ommycut\python\OmmyCut.exe"
$p = Start-Process -FilePath $exe -ArgumentList "-m studio.desktop" -WorkingDirectory "C:\ommycut" -PassThru
"launcher_pid=$($p.Id)"
Start-Sleep -Seconds 18

"--- processes"
Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match 'studio\.desktop|studio\.server|msedgewebview2' } |
  Select-Object ProcessId,Name,CommandLine | Format-Table -Wrap -AutoSize

"--- windows"
$found = @()
$cb = [WinEnum+EnumProc]{
  param($h, $l)
  if ([WinEnum]::IsWindowVisible($h)) {
    $sb = New-Object System.Text.StringBuilder 512
    [void][WinEnum]::GetWindowText($h, $sb, 512)
    $title = $sb.ToString()
    if ($title -match 'OmmyCut|WebView|Edge') {
      $pid = 0
      [void][WinEnum]::GetWindowThreadProcessId($h, [ref]$pid)
      $script:found += [pscustomobject]@{Handle=$h; Pid=$pid; Title=$title}
    }
  }
  return $true
}
[void][WinEnum]::EnumWindows($cb, [IntPtr]::Zero)
$found | Format-Table -AutoSize

$main = $found | Where-Object { $_.Title -eq "OmmyCut" } | Select-Object -First 1
if ($main) {
  [void][WinEnum]::ShowWindow($main.Handle, 9)
  [void][WinEnum]::SetForegroundWindow($main.Handle)
  Start-Sleep -Seconds 2
  Add-Type -AssemblyName System.Windows.Forms,System.Drawing
  $b = [System.Windows.Forms.SystemInformation]::VirtualScreen
  $bmp = New-Object System.Drawing.Bitmap($b.Width, $b.Height)
  $g = [System.Drawing.Graphics]::FromImage($bmp)
  $g.CopyFromScreen($b.Location, [System.Drawing.Point]::Empty, $b.Size)
  $shot = "C:\Users\soham\AppData\Local\Temp\ommycut-native.png"
  $bmp.Save($shot, [System.Drawing.Imaging.ImageFormat]::Png)
  $g.Dispose(); $bmp.Dispose()
  "screenshot=$shot"
}

