(async () => {
  const base = 'http://127.0.0.1:8799/';
  const names = ['OmmyCut-GitHub.zip','OmmyCut-Installer.exe','README.md'];
  const files = [];
  for (const name of names) {
    const r = await fetch(base + encodeURIComponent(name));
    if (!r.ok) throw new Error('fetch failed ' + name + ' ' + r.status);
    const b = await r.blob();
    files.push(new File([b], name, { type: b.type || 'application/octet-stream' }));
  }
  const target = document.querySelector('file-attachment') || document.querySelector('.js-upload-manifest-file');
  if (!target) throw new Error('drop target not found');
  const dt = new DataTransfer();
  for (const f of files) dt.items.add(f);
  for (const type of ['dragenter','dragover']) {
    target.dispatchEvent(new DragEvent(type, { bubbles:true, cancelable:true, dataTransfer: dt }));
  }
  const ev = new DragEvent('drop', { bubbles:true, cancelable:true, dataTransfer: dt });
  target.dispatchEvent(ev);
  return { dropped: files.map(f => ({name:f.name, size:f.size})), targetTag: target.tagName, targetClass: target.className };
})()

