def _stage(zip_path: Path, version: str):
    """Copy only the zip's app/ folder into app.new, refusing paths that escape it."""
    new = config.INSTALL_DIR / "app.new"
    if new.exists():
        shutil.rmtree(new, ignore_errors=True)
    new.mkdir(parents=True)
    prefix = ""
    try:
        Path(config.INSTALL_DIR / "update" / "stage-debug.txt").write_text("start zip=" + str(zip_path), encoding="utf-8")
        with zipfile.ZipFile(zip_path) as z:
            names = [i.filename.replace("\\", "/") for i in z.infolist()]
            for n in names:
                if n.endswith("app/studio/server.py"):
                    prefix = n[: -len("app/studio/server.py")]
                    break
            if not prefix and ("app/studio/server.py" in names or "studio/server.py" in names):
                prefix = ""
            elif not prefix:
                Path(config.INSTALL_DIR / "update" / "stage-debug.txt").write_text("FAIL no prefix names=" + repr(names[:10]), encoding="utf-8")
                raise RuntimeError("That zip does not contain OmmyCut's app folder.")
            want = prefix + "app/"

