"""Optional cleanup of a job's downloaded files, to the Windows recycle bin."""
from __future__ import annotations

import json
import os
import threading
import time
from pathlib import Path

from . import config, jobs, ctx

FILE = config.DATA_DIR / "cleanup.json"
_lock = threading.Lock()


def _load() -> dict:
    try:
        return json.loads(FILE.read_text(encoding="utf-8")) if FILE.exists() else {}
    except (ValueError, OSError):
        return {}


def _save(d: dict) -> None:
    FILE.parent.mkdir(parents=True, exist_ok=True)
    FILE.write_text(json.dumps(d, indent=1), encoding="utf-8")


def recycle_bin(paths) -> None:
    """Move files/folders to the Windows recycle bin. Falls back to delete on other OSes."""
    paths = [str(Path(p)) for p in (paths if not isinstance(paths, (str, Path)) else [paths])]
    paths = [p for p in paths if p]
    if not paths:
        return
    if os.name != "nt":
        for p in paths:
            try:
                Path(p).unlink() if Path(p).is_file() else __import__("shutil").rmtree(p, ignore_errors=True)
            except OSError:
                pass
        return
    import ctypes
    from ctypes import wintypes

    class SHFILEOPSTRUCTW(ctypes.Structure):
        _fields_ = [("hwnd", wintypes.HWND), ("wFunc", wintypes.UINT), ("pFrom", wintypes.LPCWSTR),
                    ("pTo", wintypes.LPCWSTR), ("fFlags", wintypes.FLAGS), ("fAnyOperationsAborted", wintypes.BOOL),
                    ("hNameMappings", wintypes.LPVOID), ("lpszProgressTitle", wintypes.LPCWSTR)]

    buf = "\0".join(paths) + "\0\0"
    op = SHFILEOPSTRUCTW()
    op.wFunc = 0x0003  # FO_DELETE
    op.pFrom = buf
    op.fFlags = 0x0040 | 0x0010 | 0x0400  # ALLOWUNDO | NOCONFIRMATION | NOERRORUI
    ctypes.windll.shell32.SHFileOperationW(ctypes.byref(op))


def job_size(jid: str) -> int:
    job = jobs.get(jid)
    if not job:
        return 0
    d = Path(job["dir"])
    if not d.exists():
        return 0
    total = 0
    for root, _, files in os.walk(d):
        for name in files:
            try:
                total += (Path(root) / name).stat().st_size
            except OSError:
                pass
    return total


def list_jobs() -> list:
    out = []
    for j in jobs.list_jobs():
        out.append({"id": j["id"], "title": j.get("title") or j.get("source", {}).get("name") or j["id"],
                    "created": j.get("created", 0), "size": job_size(j["id"]), "status": j.get("status")})
    return out


def delete_jobs(jids: list) -> int:
    n = 0
    with _lock:
        for jid in jids or []:
            job = jobs.get(jid)
            if not job:
                continue
            try:
                recycle_bin([job["dir"]])
            except Exception:  # noqa: BLE001
                pass
            jobs.forget(jid)
            n += 1
        return n


def auto_days() -> int:
    return int(_load().get("auto_delete_days", 0) or 0)


def set_auto_days(days: int) -> int:
    days = int(days or 0)
    if days not in (0, 2, 5, 7):
        days = 0
    d = _load()
    d["auto_delete_days"] = days
    _save(d)
    return days


def cleanup_old(days: int | None = None) -> int:
    if days is None:
        days = auto_days()
    if not days:
        return 0
    cutoff = time.time() - days * 86400
    to_delete = [j["id"] for j in jobs.list_jobs() if (j.get("created") or 0) < cutoff]
    return delete_jobs(to_delete)


def start() -> None:
    def loop():
        while True:
            try:
                cleanup_old()
            except Exception:  # noqa: BLE001
                pass
            time.sleep(3600)

    threading.Thread(target=loop, daemon=True, name="ommycut-cleanup").start()
    try:
        cleanup_old()
    except Exception:  # noqa: BLE001
        pass

