"""Beat-synced editing helpers: download, beat detection, SFX and rendering."""
from __future__ import annotations

import json
import subprocess
import threading
import time
import uuid
from pathlib import Path

import numpy as np
import soundfile as sf

from . import config, media

NO_WINDOW = getattr(subprocess, "CREATE_NO_WINDOW", 0)
EDITS = config.DATA_DIR / "edits"
EDITS.mkdir(parents=True, exist_ok=True)
_SFX_CACHE: dict = {}


def _run(cmd):
    return subprocess.run(cmd, capture_output=True, text=True, creationflags=NO_WINDOW)


def _ffmpeg():
    return str(config.INSTALL_DIR / "ffmpeg" / "bin" / "ffmpeg.exe")


def _download_media(url: str, work: Path, audio_only: bool = False) -> Path:
    url = url.strip()
    if not url.startswith(("http://", "https://")):
        # treat as a search term
        url = "ytsearch1:" + url
    if audio_only:
        return media.download_audio(url, work)
    return media.download(url, work, height=720)


def detect_beats(path: Path, max_beats: int = 80) -> list[float]:
    try:
        y, sr = sf.read(str(path))
    except Exception:  # noqa: BLE001
        return []
    if y.ndim > 1:
        y = y.mean(axis=1)
    hop = max(1, int(sr * 0.05))
    rms = []
    for i in range(0, len(y), hop):
        chunk = y[i:i + hop]
        rms.append(float(np.sqrt(np.mean(chunk * chunk))) if len(chunk) else 0.0)
    if not rms:
        return []
    arr = np.asarray(rms)
    thr = float(arr.mean() + 0.5 * arr.std())
    peaks = []
    for i in range(1, len(arr) - 1):
        if arr[i] > thr and arr[i] > arr[i - 1] and arr[i] > arr[i + 1]:
            t = i * 0.05
            if not peaks or t - peaks[-1] >= 0.25:
                peaks.append(t)
    return peaks[:max_beats]


def best_hook(path: Path, length: float = 15.0) -> float:
    try:
        y, sr = sf.read(str(path))
    except Exception:  # noqa: BLE001
        return 0.0
    if y.ndim > 1:
        y = y.mean(axis=1)
    hop = max(1, int(sr * 0.5))
    rms = []
    for i in range(0, len(y), hop):
        chunk = y[i:i + hop]
        rms.append(float(np.sqrt(np.mean(chunk * chunk))) if len(chunk) else 0.0)
    if not rms:
        return 0.0
    window = max(1, int(length / 0.5))
    best_i, best_val = 0, -1.0
    for i in range(0, max(1, len(rms) - window)):
        val = float(np.mean(rms[i:i + window]))
        if val > best_val:
            best_val, best_i = val, i
    return best_i * 0.5


def make_sfx(style: str, sr: int = 44100) -> Path:
    key = (style or "punch").lower()
    if key in _SFX_CACHE and Path(_SFX_CACHE[key]).is_file():
        return Path(_SFX_CACHE[key])
    dur = 0.18
    n = int(sr * dur)
    t = np.linspace(0, dur, n, endpoint=False)
    if key == "funny":
        tone = np.sin(2 * np.pi * (260 + 180 * t) * t) * np.exp(-t * 18)
        tone += 0.25 * np.sin(2 * np.pi * 620 * t) * np.exp(-t * 28)
    elif key == "angry":
        tone = np.sin(2 * np.pi * 70 * t) * np.exp(-t * 12)
        tone += 0.35 * (np.random.rand(n) - 0.5) * np.exp(-t * 18)
    elif key == "whoosh":
        tone = (np.random.rand(n) - 0.5) * np.exp(-t * 8)
    elif key == "dramatic":
        tone = np.sin(2 * np.pi * 180 * t) * np.exp(-t * 6)
        tone += 0.2 * np.sin(2 * np.pi * 360 * t) * np.exp(-t * 10)
    else:
        tone = np.sin(2 * np.pi * 120 * t) * np.exp(-t * 20)
        tone += 0.2 * (np.random.rand(n) - 0.5) * np.exp(-t * 30)
    tone = np.clip(tone, -1, 1).astype("float32")
    out = config.TMP_DIR / f"sfx-{key}.wav"
    sf.write(str(out), tone, sr)
    _SFX_CACHE[key] = str(out)
    return out


def run_edit(url: str, music: str = "", style: str = "punch", sfx: str = "punch",
             duration: int = 30, beats: bool = True) -> dict:
    work = EDITS / uuid.uuid4().hex[:12]
    work.mkdir(parents=True, exist_ok=True)
    video = _download_media(url, work, audio_only=False)
    # normalise to mp4
    src = work / "source.mp4"
    if video != src:
        _run([_ffmpeg(), "-y", "-i", str(video), "-c", "copy", str(src)])
        if not src.is_file():
            src = video

    audio_path = work / "audio.wav"
    _run([_ffmpeg(), "-y", "-i", str(src), "-vn", "-ac", "1", "-ar", "44100", str(audio_path)])

    music_path = None
    if music and music.strip():
        try:
            music_path = _download_media(music.strip(), work, audio_only=True)
            # convert to wav
            mw = work / "music.wav"
            _run([_ffmpeg(), "-y", "-i", str(music_path), "-vn", "-ac", "2", "-ar", "44100", str(mw)])
            if mw.is_file():
                music_path = mw
        except Exception:  # noqa: BLE001
            music_path = None

    beat_times = detect_beats(music_path or audio_path) if beats else []
    if not beat_times:
        beat_times = [i * 1.0 for i in range(1, max(2, duration // 2))]

    # build a single SFX track aligned to beats
    y, sr = sf.read(str(audio_path))
    sfx_sample = None
    sfx_path = make_sfx(sfx)
    sfx_y, sfx_sr = sf.read(str(sfx_path))
    if sfx_y.ndim > 1:
        sfx_y = sfx_y.mean(axis=1)
    if sfx_sr != sr:
        # resample roughly by ffmpeg? keep simple: pad/truncate
        pass
    track = np.zeros(len(y), dtype=np.float32)
    for bt in beat_times:
        idx = int(bt * sr)
        if 0 <= idx < len(track):
            end = min(len(track), idx + len(sfx_y))
            track[idx:end] += (sfx_y[:end - idx] * 0.35).astype(np.float32)
    sfx_track_path = work / "sfx.wav"
    sf.write(str(sfx_track_path), track, sr)

    out = EDITS / f"edit-{work.name}.mp4"
    dur = max(5, min(180, int(duration or 30)))
    cmd = [_ffmpeg(), "-y", "-i", str(src), "-i", str(sfx_track_path)]
    filter_complex = "[0:a]volume=0.35[a0];[1:a]volume=0.9[sfx];[a0][sfx]amix=inputs=2:duration=first:dropout_transition=0[aout]"
    if music_path and music_path.is_file():
        cmd += ["-i", str(music_path)]
        filter_complex = ("[0:a]volume=0.28[a0];[1:a]volume=0.9[sfx];[2:a]volume=0.55[music];"
                          "[a0][sfx][music]amix=inputs=3:duration=first:dropout_transition=0[aout]")
    cmd += ["-filter_complex", filter_complex, "-map", "0:v", "-map", "[aout]",
            "-t", str(dur), "-c:v", "libx264", "-crf", "20", "-preset", "fast",
            "-c:a", "aac", "-movflags", "+faststart", str(out)]
    r = _run(cmd)
    if not out.is_file():
        raise RuntimeError("Edit failed: " + (r.stderr or "")[-300:])
    return {"ok": True, "file": out.name, "url": f"/api/edit/file/{out.name}", "beats": len(beat_times), "hook": best_hook(music_path or audio_path)}
