async function drawEdit() {
  const box = $("#edit"); if (!box) return;
  box.innerHTML = `<div class="card"><h2 style="margin:0 0 6px">Edit a video</h2><p class="help">Paste a video link, pick a style, and OmmyCut builds a beat-synced edit with punchy SFX and optional music.</p>
    <form id="editForm" onsubmit="return false" style="margin-top:12px">
      <label class="f">Video link<input id="editUrl" placeholder="https://youtube.com/watch?v=..."></label>
      <label class="f">Music (optional link/name/file URL)<input id="editMusic" placeholder="song link or search term"></label>
      <div class="row" style="gap:10px;flex-wrap:wrap">
        <label class="f">Shot length<select id="editShot"><option value="fast">Fast (15s)</option><option value="medium" selected>Medium (30s)</option><option value="slow">Slow (60s)</option></select></label>
        <label class="f">Style<select id="editStyle"><option value="punch">Punchy</option><option value="funny">Funny</option><option value="angry">Angry</option><option value="dramatic">Dramatic</option><option value="whoosh">Whoosh</option></select></label>
        <label class="f">SFX<select id="editSfx"><option value="punch">Punch</option><option value="funny">Funny</option><option value="angry">Angry</option><option value="whoosh">Whoosh</option><option value="dramatic">Dramatic</option><option value="laugh">Laugh</option><option value="hit">Hit</option><option value="riser">Riser</option></select></label>
        <label class="f">Captions<select id="editCaps"><option value="off">Off</option><option value="crystal">Crystal</option><option value="jiggle">Jiggle</option><option value="bold">Bold</option><option value="minimal">Minimal</option><option value="cinematic">Cinematic</option></select></label>
      </div>
      <label class="ck"><input type="checkbox" id="editBeats" checked> Sync cuts and SFX to beats</label>
      <label class="ck"><input type="checkbox" id="editZoom" checked> Add zoom punches on beats</label>
      <div class="row" style="margin-top:12px"><button class="btn primary" data-act="editRun">Create edit</button></div>
    </form>
    <div id="editResult" style="margin-top:14px"></div></div>`;
}
async function runEdit() {
  const url = $("#editUrl")?.value.trim() || "";
  if (!url) return toast("Paste a video link.", "bad");
  const res = $("#editResult"); if (res) res.innerHTML = `<p class="help">Working… this can take a minute.</p>`;
  try {
    const r = await api("/api/edit", {method:"POST", body: JSON.stringify({
      url, music: $("#editMusic")?.value.trim() || "", style: $("#editStyle")?.value || "punch",
      sfx: $("#editSfx")?.value || "punch", captions: $("#editCaps")?.value || "off", shot: $("#editShot")?.value || "medium",
      beats: !!$("#editBeats")?.checked, zoom: !!$("#editZoom")?.checked})});
    if (res) res.innerHTML = `<p class="ok">Done. <a class="lnk" href="${esc(r.url)}" target="_blank" rel="noopener">Open edited video</a></p>`;
    toast("Edit ready.", "ok");
  } catch (e) { if (res) res.innerHTML = `<p class="help">${esc(e.message || "Edit failed.")}</p>`; toast(e.message || "Edit failed.", "bad"); }
}

