def edit_video(request: Request, body: dict = Body(...)):
    _admin(request)
    from . import edit
    try:
        return edit.run_edit(body.get("url", "").strip(), body.get("music", "").strip(),
                            body.get("style", "punch"), body.get("sfx", "punch"),
                            int(body.get("duration", 30) or 30), bool(body.get("beats", True)),
                            body.get("captions", "off"), body.get("shot", "medium"),
                            bool(body.get("zoom", True)))
    except Exception as e:  # noqa: BLE001
        raise HTTPException(422, str(e)[:300])


@app.get("/api/edit/file/{name}")
def edit_file(name: str):
    from . import edit
    p = (edit.EDITS / name).resolve()
    if not p.is_file() or edit.EDITS.resolve() not in p.parents:
        raise HTTPException(404)
    return FileResponse(p, media_type="video/mp4", headers={"Cache-Control": "private, no-store"})

