.mini-sw input{accent-color:var(--brand-deep);width:15px;height:15px;margin:0}
/* Punchy SFX: one calm card in both the clip composer and the live composer. */
.fx-card{display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:12px;border:1px solid var(--line);background:linear-gradient(120deg,#FCFCFB,#F7F4F1);transition:border-color .18s ease,background .18s ease,box-shadow .18s ease}
.fx-card.on,.fx-card:has(input:checked){border-color:var(--brand-line);background:linear-gradient(120deg,var(--brand-soft),#FFFFFF);box-shadow:0 4px 16px rgba(78,107,0,.07)}
.fx-ic{width:36px;height:36px;border-radius:11px;display:grid;place-items:center;flex:none;background:#E9E4DF;color:var(--dim);transition:background .18s ease,color .18s ease}
.fx-card.on .fx-ic,.fx-card:has(input:checked) .fx-ic{background:var(--brand);color:var(--brand-ink)}
.fx-ic svg{width:19px;height:19px}
.fx-tx{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.fx-tx b{font-size:13px;font-weight:700;color:var(--text)}
.fx-tx small{font-size:11.5px;line-height:1.35;color:var(--dim)}
.fx-switch{position:relative;display:inline-flex;flex:none;cursor:pointer}
.fx-switch input{position:absolute;opacity:0;width:1px;height:1px;margin:0}
.fx-track{width:42px;height:24px;border-radius:999px;background:#D8D2CD;display:block;position:relative;transition:background .18s ease}
.fx-track i{position:absolute;top:3px;left:3px;width:18px;height:18px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.2);transition:transform .18s ease}
.fx-switch input:checked + .fx-track{background:var(--brand-deep)}
.fx-switch input:checked + .fx-track i{transform:translateX(18px);background:var(--brand)}
.fx-switch input:focus-visible + .fx-track{outline:2px solid var(--brand);outline-offset:2px}

