"""Mood-matched sound effects for OmmyCut clips and live clips.

One toggle is all the app asks for. The sounds are REAL, licensed recordings from
bundled CC0 libraries (see app/assets/sfx/LICENSES.md), never synthesised tones.
The mood engine reads the words said around a moment, their punctuation and the
shape of the audio. It only fires when a situation is recognised with confidence;
an ordinary sentence gets no sound. Every render also gets a short, strong
viewer-hook in the first three seconds: a whoosh, a heavy hit and a visual punch.
"""
from __future__ import annotations

import json
import re
import shutil
import subprocess
import zlib
from pathlib import Path

import numpy as np
import soundfile as sf

from . import config, render
from .media import NO_WINDOW

SR = 48000
ROOT = Path(__file__).resolve().parents[1]
LIB_DIR = ROOT / "assets" / "sfx"
MANIFEST_FILE = LIB_DIR / "sounds.json"

# Phrase-first rules. A phrase is worth far more than a lone word, so "what the
# hell" fires but a passing "hell" does not. Hindi/Hinglish reactions are included
# because the app captions those streams too.
RULES: dict[str, dict] = {
    "funny": {
        "phrases": {
            "haha": 3.5, "hehe": 3.3, "lmao": 3.7, "lol": 3.1, "hilarious": 3.6,
            "that's funny": 3.5, "so funny": 3.5, "made me laugh": 3.6, "you're joking": 3.2,
            "stop it": 2.9, "i'm dead": 3.1, "im dead": 3.1, "bruh": 2.9, "cringe": 2.8,
            "goofy": 2.8, "silly": 2.7, "that's wild": 2.6, "haha haha": 3.8,
