_NEGATE = re.compile(r"\b(?:not|never|isn't|isnt|wasn't|wasnt)\s+(?:\w+\s+){0,2}")
_WORD_RE = re.compile(r"[a-z']+")
_CONF_MIN = 0.72
_SCORE_MIN = 2.6

_LIBRARY: dict | None = None
_SOUND_BY_ID: dict[str, dict] = {}
_AUDIO_CACHE: dict[str, np.ndarray] = {}


def _library() -> dict:
    global _LIBRARY, _SOUND_BY_ID
    if _LIBRARY is None:
        if not MANIFEST_FILE.is_file():
            _LIBRARY = {"count": 0, "buckets": {}, "sounds": []}
        else:
            _LIBRARY = json.loads(MANIFEST_FILE.read_text(encoding="utf-8"))
        _SOUND_BY_ID = {s["id"]: s for s in _LIBRARY.get("sounds", [])}
    return _LIBRARY


def library_count() -> int:
    """How many real CC0 sounds are bundled (used by the UI and diagnostics)."""
    return int(_library().get("count", 0))


def _norm(text: str) -> str:
    text = str(text or "").lower().replace("’", "'").replace("‘", "'")
    return re.sub(r"\s+", " ", re.sub(r"[^\w\s'!?]", " ", text)).strip()


def _has_phrase(text: str, phrase: str) -> bool:
    pattern = r"(?<!\w)" + r"\s+".join(re.escape(p) for p in _norm(phrase).split()) + r"(?!\w)"
    if not re.search(pattern, text, re.I):
        return False
    # "not funny" is not a joke. Drop the whole match when it is negated.
    if _NEGATE.search(text[: max(0, text.find(phrase.split()[0])) + 24]):
        return False
    return True


def _tokens(words) -> list[dict]:
    out = []
    for w in words or []:
        if isinstance(w, dict):
            text = str(w.get("w", "")).strip()
            try:
                s, e = float(w.get("s", 0.0)), float(w.get("e", 0.0))
            except (TypeError, ValueError):
                s = e = 0.0
        else:
            text, s, e = str(w).strip(), 0.0, 0.0
        if text:
            out.append({"w": text, "s": s, "e": e})
    return sorted(out, key=lambda x: x["s"])


def detect(text_or_words, loud: float = 1.0) -> tuple[str | None, float, str]:
    """Return (mood, confidence, evidence). Confidence is deliberately strict."""
    if isinstance(text_or_words, str):
        text = _norm(text_or_words)
    else:
        text = _norm(" ".join(w["w"] for w in _tokens(text_or_words)))
    if not text:
        return None, 0.0, ""
    scores: dict[str, float] = {}
    evidence: dict[str, list[str]] = {}
    signals = 0
    for mood, rule in RULES.items():
        score = 0.0
        hits = []
        for phrase, weight in rule["phrases"].items():
            if _has_phrase(text, phrase):
                score += weight
                hits.append(phrase)
                signals += 1
        found = set(_WORD_RE.findall(text))
        for word, weight in rule["words"].items():
            if word in found:
                score += weight
                hits.append(word)
                signals += 1
        if hits:
            scores[mood] = score
            evidence[mood] = hits
    if not scores:
        return None, 0.0, ""
    ordered = sorted(scores.items(), key=lambda kv: kv[1], reverse=True)
    mood, top = ordered[0]
    second = ordered[1][1] if len(ordered) > 1 else 0.0
    if top < _SCORE_MIN:
        return None, round(min(0.69, 0.2 + top / 9), 2), ",".join(evidence[mood][:3])
    punctuation = 1 if "!" in text or "?" in text else 0
    repeated = 1 if re.search(r"\b(\w+)\s+\1\b", text, re.I) else 0
    loud_signal = 1 if loud >= 1.55 else 0
    conf = 0.42 + 0.16 * top + 0.035 * (top - second) + 0.04 * (signals + punctuation + repeated + loud_signal)
    conf = round(min(0.99, conf), 2)
    if conf < _CONF_MIN:
        return None, conf, ",".join(evidence[mood][:3])
    return mood, conf, ",".join(evidence[mood][:3])


def classify(words) -> str | None:
    """Compatibility helper: the detected mood, or None when not confident."""
    mood, _, _ = detect(words)
    return mood


def _near(words, t_abs: float, window: float = 1.7) -> list[dict]:
    return [w for w in words if w["e"] >= t_abs - window and w["s"] <= t_abs + window]


def _peaks(src: Path, start: float, end: float, limit: int = 12) -> list[tuple[float, float]]:
    rms = render.clip_loudness(src, start, end)
    if len(rms) < 12 or float(rms.max()) < 45:
        return []
    floor = max(1.0, float(np.median(rms)))
    threshold = max(floor * 1.5, float(np.percentile(rms, 80)))
    picked = []
    for i in np.argsort(rms)[::-1]:
        if rms[i] < threshold or len(picked) >= limit:
            break
        t = round(float(i) * 0.05, 2)
        if t < 0.7 or t > end - start - 0.35:
            continue
        if any(abs(t - p[0]) < 1.1 for p in picked):
            continue
        picked.append((t, float(rms[i]) / floor))
    return sorted(picked)


def _phrase_groups(tokens: list[dict]) -> list[tuple[float, float, str]]:
    groups: list[list[dict]] = []
    cur: list[dict] = []
    for w in tokens:
        if cur and (w["s"] - cur[-1]["e"] > 0.55 or len(cur) >= 8):
            groups.append(cur)
            cur = []
        cur.append(w)
    if cur:
        groups.append(cur)
    out = []
    for g in groups:
        out.append((g[0]["s"], g[-1]["e"], " ".join(x["w"] for x in g)))
    return out


def hook_word(words, start: float = 0.0, end: float = 0.0) -> str:
    """The big word that flashes on screen in the first three seconds."""
    tokens = _tokens(words)
    text = " ".join(w["w"] for w in tokens if w["s"] <= start + 3.2)
    mood, conf, _ = detect(text or tokens)
    if conf < 0.75:
        return "OMMYCUT"
    return {"funny": "LOL", "angry": "RAGE", "shock": "NO WAY", "win": "LET'S GO",
            "hit": "BOOM", "dramatic": "WTF?", "whoosh": "GO!", "scare": "RUN!"}.get(mood, "OMMYCUT")


def plan(src: Path, start: float, end: float, words, length: float, keep=None) -> list[dict]:
    """Plan every sound in seconds of the FINISHED clip. No guesswork, no random hits."""
    dur = max(0.0, float(end) - float(start))
    if length < 1.2 or dur < 1.2 or library_count() < 100:
        return []
    tokens = _tokens(words)
    first_text = " ".join(w["w"] for w in tokens if w["s"] <= start + 3.0)
    first_mood, _, _ = detect(first_text or _near(tokens, start + 1.0))

    events: list[dict] = [
        {"t": 0.0, "mood": "whoosh", "gain": 0.72, "key": "hook-whoosh", "kind": "hook", "confidence": 1.0},
        {"t": 0.26 if length >= 1.0 else 0.08, "mood": "hook", "gain": 0.98,
         "key": "hook-impact", "kind": "hook", "confidence": 1.0},
    ]
    if first_mood in ("win", "funny", "shock", "hit"):
        events.append({"t": 0.46, "mood": first_mood, "gain": 0.72,
                       "key": "hook-accent", "kind": "hook", "confidence": 1.0})

    candidates: dict[float, dict] = {}

    def consider(raw_t: float, center_t: float | None, loud: float, key: str) -> None:
        if not (0.8 <= raw_t <= dur - 0.35):
            return
        ctx = _near(tokens, start + raw_t) if center_t is None else _near(tokens, center_t)
        mood, conf, ev = detect(ctx, loud)
        if not mood or conf < _CONF_MIN:
            return
        old = candidates.get(round(raw_t, 1))
        if old and old["confidence"] >= conf:
            return
        candidates[round(raw_t, 1)] = {
            "t": round(raw_t, 3), "mood": mood,
            "gain": round(float(np.clip(0.52 + 0.34 * (conf - 0.7) + 0.05 * (loud - 1), 0.5, 0.78)), 3),
            "key": f"{key}|{ev}|{mood}", "kind": "mood", "confidence": conf,
        }

    # Spoken phrases: a quiet "no way" still deserves a sound.
    for a, b, phrase in _phrase_groups(tokens):
        raw_t = b - start
        if 0.8 <= raw_t <= dur - 0.35:
            consider(raw_t, (a + b) / 2, 1.0, phrase)

    # Loud reactions: the words around a shout or punch decide what it means.
    for t, strength in _peaks(src, start, end):
        consider(t, start + t, strength, f"peak-{t}")

    used: list[float] = []
    for c in sorted(candidates.values(), key=lambda x: (-x["confidence"], x["t"])):
        if any(abs(c["t"] - u) < 1.15 for u in used):
            continue
        t = render._remap(c["t"], keep) if keep else c["t"]
        if t is None or not (0.75 <= t <= length - 0.18):
            continue
        used.append(c["t"])
        c = dict(c, t=round(float(t), 3))
        events.append(c)
        # High-confidence moments get one small, matching accent, never a random extra.
        if c["confidence"] >= 0.9 and c["mood"] in ("win", "funny", "hit", "shock"):
            at = c["t"] + 0.11
            if at < length - 0.1:
                events.append({"t": round(at, 3), "mood": c["mood"], "gain": 0.42,
                               "key": c["key"] + "|accent", "kind": "accent", "confidence": c["confidence"]})

    events.sort(key=lambda e: e["t"])
    return events[:16]


def _pick_sound(mood: str, key: str, used: set[str]) -> dict | None:
    lib = _library()
    ids = lib.get("buckets", {}).get(mood) or lib.get("buckets", {}).get("whoosh") or []
    if not ids:
        return None
    h = zlib.crc32(f"{mood}|{key}".encode("utf-8"))
    for i in range(len(ids)):
        sid = ids[(h + i) % len(ids)]
        if sid in used:
            continue
        sound = _SOUND_BY_ID.get(sid)
        if sound and (LIB_DIR / sound["file"]).is_file():
            used.add(sid)
            return sound
    sid = ids[h % len(ids)]
    return _SOUND_BY_ID.get(sid)


def _sample(sound: dict) -> np.ndarray:
    sid = sound["id"]
    if sid not in _AUDIO_CACHE:
        data, sr = sf.read(str(LIB_DIR / sound["file"]), dtype="float32", always_2d=True)
        if data.shape[1] > 1:
            data = data.mean(axis=1)
        else:
            data = data[:, 0]
        if sr != SR:
            n = int(round(len(data) * SR / sr))
            data = np.interp(np.linspace(0, len(data) - 1, n), np.arange(len(data)), data).astype(np.float32)
        peak = float(np.max(np.abs(data))) if len(data) else 0.0
        if peak > 0:
            data = data * (0.9 / peak)
        _AUDIO_CACHE[sid] = data.astype(np.float32)
        if len(_AUDIO_CACHE) > 160:
            for old in list(_AUDIO_CACHE)[:60]:
                _AUDIO_CACHE.pop(old, None)
    return _AUDIO_CACHE[sid]


def write_track(path: Path, events: list, length: float, sr: int = SR) -> Path:
    """Mix the chosen real recordings into one WAV the length of the finished clip."""
    n = max(1, int(float(length) * sr))
    track = np.zeros(n, dtype=np.float32)
    used: set[str] = set()
    for event in events:
        if isinstance(event, dict):
            t = float(event.get("t", 0.0))
            mood = str(event.get("mood", "whoosh"))
            gain = float(event.get("gain", 0.6))
            key = str(event.get("key", mood))
        else:  # old three-part tuples, for compatibility with any queued job
            t, mood, gain = float(event[0]), str(event[1]), float(event[2])
            key = f"{mood}-{t}"
        sound = _pick_sound(mood, key, used)
        if not sound:
            continue
        clip = _sample(sound)
        sync = float(sound.get("sync_at", 0.0) or 0.0)
        if event.get("kind") == "hook" and mood != "whoosh":
            sync = float(sound.get("sync_at", 0.0) or 0.0)  # land the hit exactly on its peak
        at = int(max(0.0, t - min(sync, len(clip) / sr)) * sr)
        if at >= n:
            continue
        end = min(n, at + len(clip))
        piece = clip[: end - at] * gain
        fade = min(int(sr * 0.008), max(1, len(piece) // 4))
        if len(piece) > fade * 2:
            ramp = np.linspace(0, 1, fade, dtype=np.float32)
            piece[:fade] *= ramp
            piece[-fade:] *= ramp[::-1]
        track[at:end] += piece
    peak = float(np.max(np.abs(track))) if n else 0.0
    if peak > 0.94:
        track *= 0.94 / peak
    fade = int(sr * 0.012)
    if n > fade * 2:
        ramp = np.linspace(0, 1, fade, dtype=np.float32)
        track[:fade] *= ramp
        track[-fade:] *= ramp[::-1]
    path.parent.mkdir(parents=True, exist_ok=True)
    sf.write(str(path), track, sr, subtype="PCM_16")
    return path


def add_to_video(video: Path, sfx_wav: Path, work: Path) -> bool:
    """Mix the SFX under an already-rendered clip, ducking the voice for the hook. Never fatal."""
    if not video.is_file() or not sfx_wav.is_file():
        return False
    out = work / "with-sfx.mp4"
    # The first 0.62 s are ducked so the hook can be felt without burying the first words.
    mix = ("[0:a]volume=if(lt(t\\,0.62)\\,0.58\\,0.95):eval=frame[a0];[1:a]volume=0.82[fx];"
           "[a0][fx]amix=inputs=2:duration=first:dropout_transition=0:normalize=0,"
           "alimiter=limit=0.95:attack=5:release=50[a]")
    commands = [
        ["ffmpeg", "-y", "-v", "error", "-i", str(video), "-i", str(sfx_wav),
         "-filter_complex", mix, "-map", "0:v", "-map", "[a]", "-c:v", "copy",
         "-c:a", "aac", "-b:a", "160k", "-ar", "48000", "-movflags", "+faststart",
         "-shortest", str(out)],
        # A source with no sound track: the SFX becomes the whole audio.
        ["ffmpeg", "-y", "-v", "error", "-i", str(video), "-i", str(sfx_wav),
         "-map", "0:v", "-map", "1:a", "-c:v", "copy", "-c:a", "aac",
         "-b:a", "160k", "-ar", "48000", "-shortest", str(out)],
    ]
    for cmd in commands:
        try:
            p = subprocess.run(cmd, capture_output=True, text=True, timeout=180, creationflags=NO_WINDOW)
        except (OSError, subprocess.TimeoutExpired):
            continue
        if p.returncode == 0 and out.is_file() and out.stat().st_size > 1024:
            shutil.move(str(out), str(video))
            return True
        if p.returncode != 0:
            print("  SFX mix note:", (p.stderr or "").strip()[-180:], flush=True)
    try:
        out.unlink(missing_ok=True)
    except OSError:
        pass
    return False

