 /* One toggle, in both the normal clip composer and the live composer. The rest is automatic. */
 function sfxCard(on, id, dataF = "") {
   return `<div class="fx-card ${on ? "on" : ""}"><span class="fx-ic">${ic("sparkle")}</span>
-    <span class="fx-tx"><b>Punchy sound effects</b><small>Listens for jokes, rage, wins and big hits, then drops the right sound by itself.</small></span>
+    <span class="fx-tx"><b>Smart SFX + 3s hook</b><small>1,684 real sounds. Fires only on a clear mood and opens every clip with a punch.</small></span>
     <label class="fx-switch" title="Turn automatic situation-based SFX on or off"><input type="checkbox" id="${id}" ${dataF ? `data-f="${dataF}"` : ""} ${on ? "checked" : ""}><span class="fx-track"><i></i></span></label></div>`;
 }
 function syncFxCards() { $$(".fx-card").forEach(card => { const input = $("input", card); if (input) card.classList.toggle("on", input.checked); }); }

